-- Run in Supabase SQL Editor. Keeps existing tables and adds v2 RPC functions.
begin;
create extension if not exists pgcrypto;
create unique index if not exists intz_sessions_user_local_uidx on public.intz_sessions(user_key,local_id);
create unique index if not exists intz_workouts_user_local_uidx on public.intz_workouts(user_key,local_id);
alter table public.intz_accounts enable row level security; alter table public.intz_sessions enable row level security; alter table public.intz_workouts enable row level security;
revoke all on public.intz_accounts,public.intz_sessions,public.intz_workouts from anon,authenticated;
create or replace function public.intz_v2_check_secret(k text,s text) returns boolean language sql stable security definer set search_path=public,extensions as $$select exists(select 1 from intz_accounts a where a.user_key=lower(trim(k)) and a.secret_hash=crypt(s,a.secret_hash))$$;
create or replace function public.intz_v2_register_or_verify(p_user_key text,p_sync_secret text) returns boolean language plpgsql security definer set search_path=public,extensions as $$declare k text:=lower(trim(p_user_key));begin if k='' or k='default' or length(p_sync_secret)<12 then raise exception 'Ugyldig profil eller synknøkkel';end if;insert into intz_accounts(user_key,secret_hash,created_at,updated_at)values(k,crypt(p_sync_secret,gen_salt('bf')),now(),now())on conflict(user_key)do nothing;if not intz_v2_check_secret(k,p_sync_secret)then raise exception 'Feil synknøkkel';end if;return true;end$$;
create or replace function public.intz_v2_upsert_session(p_user_key text,p_sync_secret text,p_session jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare k text:=lower(trim(p_user_key));lid text:=coalesce(p_session->>'_local_id',p_session->>'id');begin if not intz_v2_check_secret(k,p_sync_secret)then raise exception 'Ikke autorisert';end if;insert into intz_sessions(user_key,local_id,name,started_at,ended_at,payload,schema_version,client_updated_at,deleted_at,created_at,server_updated_at)values(k,lid,coalesce(p_session->>'name','Økt'),nullif(p_session->>'startedAt','')::timestamptz,nullif(p_session->>'endedAt','')::timestamptz,p_session,2,coalesce(nullif(p_session->>'_updated_at','')::timestamptz,now()),nullif(p_session->>'_deleted_at','')::timestamptz,now(),now())on conflict(user_key,local_id)do update set name=excluded.name,started_at=excluded.started_at,ended_at=excluded.ended_at,payload=excluded.payload,client_updated_at=excluded.client_updated_at,deleted_at=excluded.deleted_at,server_updated_at=now();return jsonb_build_object('local_id',lid);end$$;
create or replace function public.intz_v2_list_session_summaries(p_user_key text,p_sync_secret text) returns table(local_id text,name text,started_at timestamptz,ended_at timestamptz,duration_sec numeric,distance_m numeric,client_updated_at timestamptz,deleted_at timestamptz,source jsonb) language plpgsql security definer set search_path=public,extensions as $$begin if not intz_v2_check_secret(p_user_key,p_sync_secret)then raise exception 'Ikke autorisert';end if;return query select s.local_id,s.name,s.started_at,s.ended_at,extract(epoch from(s.ended_at-s.started_at))::numeric,coalesce(nullif(s.payload#>>'{points,-1,dist_m}','')::numeric,0),s.client_updated_at,s.deleted_at,s.payload->'source' from intz_sessions s where s.user_key=lower(trim(p_user_key)) order by s.started_at;end$$;
create or replace function public.intz_v2_get_session(p_user_key text,p_sync_secret text,p_local_id text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare x jsonb;begin if not intz_v2_check_secret(p_user_key,p_sync_secret)then raise exception 'Ikke autorisert';end if;select payload into x from intz_sessions where user_key=lower(trim(p_user_key))and local_id=p_local_id and deleted_at is null;return x;end$$;
create or replace function public.intz_v2_delete_session(p_user_key text,p_sync_secret text,p_local_id text,p_client_updated_at timestamptz) returns boolean language plpgsql security definer set search_path=public,extensions as $$begin if not intz_v2_check_secret(p_user_key,p_sync_secret)then raise exception 'Ikke autorisert';end if;update intz_sessions set deleted_at=coalesce(p_client_updated_at,now()),client_updated_at=coalesce(p_client_updated_at,now()),server_updated_at=now()where user_key=lower(trim(p_user_key))and local_id=p_local_id;return true;end$$;
create or replace function public.intz_v2_upsert_workouts(p_user_key text,p_sync_secret text,p_items jsonb) returns integer language plpgsql security definer set search_path=public,extensions as $$declare k text:=lower(trim(p_user_key));x jsonb;n int:=0;begin if not intz_v2_check_secret(k,p_sync_secret)then raise exception 'Ikke autorisert';end if;for x in select value from jsonb_array_elements(p_items)loop insert into intz_workouts(user_key,local_id,name,description,payload,schema_version,client_updated_at,deleted_at,created_at,server_updated_at)values(k,coalesce(x->>'_local_id',x->>'id'),coalesce(x->>'name','Øktmal'),coalesce(x->>'desc',''),x,2,coalesce(nullif(x->>'_updated_at','')::timestamptz,now()),nullif(x->>'_deleted_at','')::timestamptz,now(),now())on conflict(user_key,local_id)do update set name=excluded.name,description=excluded.description,payload=excluded.payload,client_updated_at=excluded.client_updated_at,deleted_at=excluded.deleted_at,server_updated_at=now();n:=n+1;end loop;return n;end$$;
create or replace function public.intz_v2_list_workouts(p_user_key text,p_sync_secret text) returns table(local_id text,payload jsonb,client_updated_at timestamptz,deleted_at timestamptz) language plpgsql security definer set search_path=public,extensions as $$begin if not intz_v2_check_secret(p_user_key,p_sync_secret)then raise exception 'Ikke autorisert';end if;return query select w.local_id,w.payload,w.client_updated_at,w.deleted_at from intz_workouts w where w.user_key=lower(trim(p_user_key));end$$;
grant execute on function public.intz_v2_register_or_verify(text,text),public.intz_v2_upsert_session(text,text,jsonb),public.intz_v2_list_session_summaries(text,text),public.intz_v2_get_session(text,text,text),public.intz_v2_delete_session(text,text,text,timestamptz),public.intz_v2_upsert_workouts(text,text,jsonb),public.intz_v2_list_workouts(text,text) to anon,authenticated;
commit;
